python3 - <<'EOF'
import json, glob

total = 0
for f in sorted(glob.glob('data/*.jsonl')):
    for line in open(f):
        line = line.strip()
        if not line:
            continue
        rec = json.loads(line)
        if rec.get('kind') != 'span':
            continue
        elapsed = rec.get('body', {}).get('span', {}).get('elapsed')
        if elapsed is None:
            continue  # counts as 0
        value = elapsed['value']
        unit = elapsed['unit']
        if unit == 'ms':
            total += value
        elif unit == 'us':
            total += value // 1000
        elif unit == 's':
            total += value * 1000
        else:
            raise ValueError(unit)
print(total)
EOF

python3 - <<'EOF'
import json, glob
from collections import Counter
kinds = Counter(); units = Counter(); noelapsed = 0; nonint = 0
for f in sorted(glob.glob('data/*.jsonl')):
    for line in open(f):
        line=line.strip()
        if not line: continue
        rec = json.loads(line)
        kinds[rec.get('kind')] += 1
        if rec.get('kind') == 'span':
            el = rec.get('body', {}).get('span', {}).get('elapsed')
            if el is None:
                noelapsed += 1
            else:
                units[el['unit']] += 1
                if not isinstance(el['value'], int):
                    nonint += 1
print(kinds, units, 'noelapsed', noelapsed, 'nonint', nonint)
EOF
